Local Ltac mem_after_store ::= mem_after_store_fast.

Section COPYSPP.
Variable RT : rt_sig.
Hypothesis AF : art_facts RT.
Hypothesis GP : rt_gaps RT.

Theorem pixCopySpp_ok : pixCopySpp_cps RT.
Proof using AF GP.
Ltac finish SG VD pd PDIN PD0 PD16 PDN PDOK PDD CMK AGF ESP QF RT Hc0 :=
    apply cps_finish; let c := fresh "c" in let Hc := fresh "Hc" in intros c Hc; subst QF; cbv beta;
    exists SG, VD;
    split; [| repeat split; first [reflexivity | assumption | lia]];
    eapply (ASTA_conseq RT); [exact Hc|]; intros ms <-; eexists;
    split; [split; [unfold ret_st; try rewrite ESP; do 16 eexists; reflexivity| cbn [ms_fregs MS]; fs_agree_tac]|];
    split; [split; [split; [assumption| split; [assumption| split; [| assumption]]]| split; assumption];
            repeat match goal with H : wmono asegs _ _ |- _ => revert H end; clear; intros; eauto using wmono_trans |];
    split; [let a := fresh "a" in let Ha := fresh "Ha" in let Ho := fresh "Ho" in intros a Ha Ho; apply AGF; split;
            [first [exact Ha | match goal with E : rt_live RT _ = rt_live RT _ |- _ => first [rewrite E in Ha; exact Ha | rewrite <- E in Ha; exact Ha] end]| exact Ho]|];
    split; [| split; [repeat split; reflexivity| reflexivity]];
    try match goal with E : rt_live RT _ = rt_live RT _ |- _ => rewrite E end;
    unfold pix_obj, pix_cells; cbn [p_w p_h p_d p_spp p_wpl p_xres p_yres p_inf p_spec p_cmap p_data];
    split; [lazymatch goal with H : rw_cells asegs ?mf pd _ |- rw_cells asegs ?mf pd _ => exact H end|];
    split; [exact (conj PDIN (conj PD0 (conj PD16 PDN)))|]; split; [exact PDOK|]; split; [exact PDD| apply CMK; exact AGF].
